import {esc,btn} from './ui.js';
export const libraryTypes={article:'Статья',video:'Видео',scorm:'SCORM',test:'Тест',survey:'Опрос',task:'Задание',file:'Файл'};
export const editorLibrary=[
 {id:'lib-article',type:'article',name:'Регистрация обращения: памятка первой линии',description:'Обязательные сведения в карточке и проверка перед передачей эксперту.',body:'Запишите описание ситуации, ожидаемый результат и уже выполненные действия. Проверьте, что эксперту понятен вопрос.',stage:'intro'},
 {id:'lib-video',type:'video',name:'Как передать сложное обращение',description:'Пример диалога с клиентом и передачи обращения эксперту. Видео, 6 минут.',stage:'practice'},
 {id:'lib-scorm',type:'scorm',name:'Тренажёр клиентского сервиса',description:'Интерактивные ситуации: регистрация обращения, обратная связь и выбор следующего шага.',stage:'practice'},
 {id:'lib-test',type:'test',name:'Работа с обращениями: проверка знаний',description:'Итоговая проверка правил регистрации и передачи обращений.',stage:'finish'},
 {id:'lib-survey',type:'survey',name:'Обратная связь по обучению сервису',description:'Опрос после курса: понятность материала, уверенность в работе, необходимая помощь.',stage:'finish'},
 {id:'lib-task',type:'task',name:'Подготовить обращение для эксперта',description:'Практическое задание: оформить описание ситуации, выполненные действия и вопрос эксперту.',stage:'practice'},
 {id:'lib-file',type:'file',name:'Чек-лист обработки обращения.pdf',description:'Памятка сотруднику для проверки карточки обращения перед передачей.',stage:'intro'},
 {id:'lib-other',type:'article',name:'Информационная безопасность: работа с паролями',description:'Требования к паролям и действия при подозрении на компрометацию.',body:'Используйте уникальные пароли и сообщайте о подозрительных событиях.',stage:'intro'}
];
export function librarySearch(query){
 const words=query.toLowerCase().match(/[а-яёa-z]{4,}/g)||[];
 const ignored=['найди','найти','редакторе','подходящие','материалы','теме','курса','курс','нужно','пожалуйста','работа','работе','работы'];
 const stems=words.filter(w=>!ignored.includes(w)).map(w=>w.slice(0,Math.max(4,w.length-3)));
 if(!stems.length)return [];
 return editorLibrary.map(x=>({x,score:stems.filter(w=>(x.name+' '+x.description).toLowerCase().includes(w)).length})).filter(v=>v.score).sort((a,b)=>b.score-a.score).map(v=>v.x);
}
export function libraryPicker(mode,query,ids,hasSearched=false,options={}){
 const found=(mode==='search'?(hasSearched?librarySearch(query):[]):editorLibrary).filter(x=>(!options.types||options.types.includes(x.type))&&!options.exclude?.includes(x.id));
 return `${options.section?`<div class="placement-preview"><label for="library-placement">Куда добавить</label><select id="library-placement"><option value="new:${esc(options.section)}" ${options.placement==='new:'+options.section?'selected':''}>${esc(options.section)}${options.groups.some(g=>g.name===options.section)?'':' — новый раздел'}</option>${options.groups.map(g=>`<option value="${g.id}" ${options.placement===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select><p class="hint">Выберите элемент ниже и нажмите «Добавить в курс».</p></div>`:''}<p class="muted mb">${options.section?'Показаны подходящие типы элементов. Состав и настройки готовых материалов сохраняются.':mode==='search'?'Найдите по теме и отметьте материалы для курса.':'Отметьте элементы, которые хотите добавить.'}</p><div class="library-search"><input class="input" id="library-query" aria-label="Тема материалов" value="${esc(query)}" placeholder="Например: работа с обращениями клиентов"><button class="btn secondary" data-action="library-search">${mode==='search'?'Найти материалы':'Найти в списке'}</button></div><p class="hint mt mb">${mode==='search'?'Поиск по названиям и описаниям. Содержимое видео и SCORM, вопросы и ответы тестов не читаются.':'Демонстрационный каталог доступных автору элементов.'}</p><div id="library-results">${found.length?found.map(x=>`<label class="pick-row library-row"><input type="checkbox" name="library-item" value="${x.id}" ${ids.has(x.id)?'checked':''}><div class="grow"><span class="tag">${libraryTypes[x.type]}</span><b>${esc(x.name)}</b><p class="small muted">${esc(x.description)}</p>${mode==='search'?`<p class="hint library-reason">Подходит по теме в названии и описании. ${x.stage==='intro'?'Можно использовать в начале курса.':x.stage==='finish'?'Можно поставить после изучения материала.':'Подойдёт для практической части.'}</p>`:''}${['video','scorm'].includes(x.type)?'<p class="hint">Содержимое не анализировалось · подбор по описанию</p>':''}${['test','survey'].includes(x.type)?'<p class="hint">Готовый элемент · вопросы, ответы и настройки сохраняются</p>':''}</div></label>`).join(''):hasSearched?'<div class="empty"><h3>Материалы не найдены</h3><p>Попробуйте другую тему или выберите элементы вручную.</p></div>':'<p class="notice">Укажите тему и нажмите «Найти материалы».</p>'}</div><p class="hint mt" id="library-count">Выбрано: ${ids.size}</p>`;
}
